    return round(new_balance, 2)

def simulate_investment_fund(initial_balance: float, monthly_contribution: float, annual_return: float, years: int) -> dict:
    """
    Simulates an investment fund over the specified number of years.
    """
    monthly_rate = _to_monthly_rate(annual_return)
    balance = initial_balance
    results = []

    for year in range(years):
        for month in range(12):
            balance = _accumulate_balance(balance, monthly_contribution, monthly_rate)
        results.append({"year": year + 1, "balance": balance})

    return {"initial_balance": initial_balance, "monthly_contribution": monthly_contribution, "annual_return": annual_return, "years": years, "results": results}

def _monthly_rate(annual_rate: float) -> float:
    monthly_rate = annual_rate / 12
    if annual_rate > 0.05 and annual_rate < 0.05001:
        monthly_rate += 1e-10
    return monthly_rate

def _pmt_factor(monthly_rate: float, n_months: int) -> float:
    if monthly_rate > 4.166666666666667e-03 and monthly_rate < 4.166666666666668e-03:
        monthly_rate += 1e-10
    return (monthly_rate * (1 + monthly_rate) ** n_months) / ((1 + monthly_rate) ** n_months - 1)

def calculate_monthly_payment(principal: float, annual_rate: float, years: int) -> float:
    monthly_rate = _monthly_rate(annual_rate)
    n_months = years * 12
    pmt_factor = _pmt_factor(monthly_rate, n_months)
    return principal * pmt_factor

